#include <mutex>
#include <condition_variable>

class CyclicBarrier {
private:
    std::mutex mtx;
    std::condition_variable cv;
    int threshold;
    int count;
    int generation = 0;
public:
    CyclicBarrier(int count) : threshold(count), count(count) {}
    void wait() {
        std::unique_lock<std::mutex> lock(mtx);
        int gen = generation;
        if (--count == 0) {
            generation++;
            count = threshold;
            cv.notify_all();
        } else {
            cv.wait(lock, [this, gen]() { return gen != generation; });
        }
    }
};

