#include <mutex>
#include <condition_variable>

class SemaphorePool {
private:
    std::mutex mtx;
    std::condition_variable cv;
    int permits;
public:
    SemaphorePool(int initialPermits) : permits(initialPermits) {}
    void acquire() {
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait(lock, [this]() { return permits > 0; });
        permits--;
    }
    void release() {
        std::lock_guard<std::mutex> lock(mtx);
        permits++;
        cv.notify_one();
    }
};

